class Solution:
    def replaceWords(self, dictionary: list[str], sentence: str) -> str:
        roots = set(dictionary)
        words = sentence.split()
        for i, word in enumerate(words):
            for length in range(1, len(word) + 1):
                if word[:length] in roots:
                    words[i] = word[:length]
                    break
        return ' '.join(words)
